    def build(self, node, gds_collector_=None):
        self.gds_collector_ = gds_collector_
        if SaveElementTreeNode:
            self.gds_elementtree_node_ = node
        already_processed = set()
        self.ns_prefix_ = node.prefix
        self._buildAttributes(node, node.attrib, already_processed)
        for child in node:
            nodeName_ = Tag_pattern_.match(child.tag).groups()[-1]
            self._buildChildren(child, node, nodeName_, gds_collector_=gds_collector_)
        return self

    def _buildAttributes(self, node, attrs, already_processed):
        value = find_attr_value_("xml:id", node)
        if value is not None and "id" not in already_processed:
            already_processed.add("id")
            self.id = value

    def _buildChildren(self, child_, node, nodeName_, fromsubclass_=False, gds_collector_=None):
        if nodeName_ == "vendor":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "vendor")
            value_ = self.gds_validate_string(value_, node, "vendor")
            self.vendor = value_
            self.vendor_nsprefix_ = child_.prefix
        elif nodeName_ == "library":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "library")
            value_ = self.gds_validate_string(value_, node, "library")
            self.library = value_
            self.library_nsprefix_ = child_.prefix
        elif nodeName_ == "name":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "name")
            value_ = self.gds_validate_string(value_, node, "name")
            self.name = value_
            self.name_nsprefix_ = child_.prefix
        elif nodeName_ == "version":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "version")
            value_ = self.gds_validate_string(value_, node, "version")
            self.version = value_
            self.version_nsprefix_ = child_.prefix
        elif nodeName_ == "displayName":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "displayName")
            value_ = self.gds_validate_string(value_, node, "displayName")
            self.displayName = value_
            self.displayName_nsprefix_ = child_.prefix
        elif nodeName_ == "shortDescription":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "shortDescription")
            value_ = self.gds_validate_string(value_, node, "shortDescription")
            self.shortDescription = value_
            self.shortDescription_nsprefix_ = child_.prefix
        elif nodeName_ == "description":
            value_ = child_.text
            value_ = self.gds_parse_string(value_, node, "description")
            value_ = self.gds_validate_string(value_, node, "description")
            self.description = value_
            self.description_nsprefix_ = child_.prefix
        elif nodeName_ == "typeDefinitions":
            obj_ = typeDefinitionsType.factory(parent_object_=self)
            obj_.build(child_, gds_collector_=gds_collector_)
            self.typeDefinitions = obj_
            obj_.original_tagname_ = "typeDefinitions"
        elif nodeName_ == "powerDomains":
            obj_ = powerDomainsType.factory(parent_object_=self)
            obj_.build(child_, gds_collector_=gds_collector_)
