class clearboxElementType(GeneratedsSuper):
    """name -- Unique name
    clearboxType -- Indicates the type of the element. The pin and signal types refer to elements within the HDL description. The interface type refers to a group of signals addressed as a single unit.
    driveable -- If true, indicates that the clear box element can be driven (e.g. have a new value forced into it).

    """

    __hash__ = GeneratedsSuper.__hash__
    subclass = None
    superclass = None

    def __init__(
        self,
        id=None,
        name=None,
        displayName=None,
        shortDescription=None,
        description=None,
        clearboxType=None,
        driveable=False,
        parameters=None,
        vendorExtensions=None,
        gds_collector_=None,
        **kwargs_,
    ):
        self.gds_collector_ = gds_collector_
